delete from documents where business_id='smile-point' and source_uri='smile-point/faq.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('smile-point','smile-point/faq.md','faq','be47e3e477c3a2db1c2d9b4fb08fa00ad16c2b273088f3b2a8ede02b040927d5') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'smile-point',0,'Location','We are at 14, 2nd Avenue, Anna Nagar, Chennai 600040, above the Canara Bank branch.
Parking for two-wheelers is available in front. Car parking is on the side street.'),((select id from d),'smile-point',1,'Opening Hours','Monday to Saturday: 9:30 AM to 1:30 PM and 4:30 PM to 8:30 PM.
Sunday: 10:00 AM to 1:00 PM, emergencies only.'),((select id from d),'smile-point',2,'Payment','We accept cash, UPI, and all major debit and credit cards. No-cost EMI is available on braces and aligners through Bajaj Finserv.'),((select id from d),'smile-point',3,'Insurance','We do not bill insurance directly. We give you an itemised invoice so you can claim reimbursement from your insurer.'),((select id from d),'smile-point',4,'Languages','Our doctors speak Tamil, English and Hindi.'),((select id from d),'smile-point',5,'Doctors','Dr. Priya Raman (BDS, MDS) — orthodontics, braces and aligners.
Dr. Karthik Subramanian (BDS) — general dentistry, root canals, crowns.'),((select id from d),'smile-point',6,'Emergencies','For severe tooth pain, swelling or a broken tooth, call +91 98400 00000. We keep two emergency slots every day.');
delete from documents where business_id='smile-point' and source_uri='smile-point/policies.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('smile-point','smile-point/policies.md','policies','1d9fa7f75d529c35b8d1b6e41680626c9a8e3d833716dd5cfab287a33b99ed77') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'smile-point',0,'Booking','Appointments can be booked by phone, WhatsApp or walk-in. We confirm every booking on WhatsApp.'),((select id from d),'smile-point',1,'Cancellation and Rescheduling','Please cancel or reschedule at least 4 hours before your appointment. You can reschedule twice at no charge.'),((select id from d),'smile-point',2,'No-shows','If you miss an appointment without informing us twice, we ask for a Rs 500 advance for your next booking. The advance is adjusted in your bill.'),((select id from d),'smile-point',3,'Late Arrival','If you are more than 15 minutes late, we may need to move you to the next free slot.'),((select id from d),'smile-point',4,'First Visit','Please bring any previous X-rays and a list of medicines you take. The first visit takes about 30 minutes.');
delete from documents where business_id='smile-point' and source_uri='smile-point/prices.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('smile-point','smile-point/prices.md','prices','2bc70ce93ed6e05cba49052914f59c19abbea34102f6b8d8a591549c0c1608a4') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'smile-point',0,'Smile Point Dental — Price List (2026)','All prices are in Indian Rupees and include GST. Final cost is confirmed by the doctor after examination.'),((select id from d),'smile-point',1,'Consultation','General consultation: Rs 500. Free if you book a treatment the same day.
Second-opinion consultation (bring your old X-rays and treatment plan): Rs 500.'),((select id from d),'smile-point',2,'X-rays and Scans','Digital X-ray (RVG, single tooth): Rs 300.
Full mouth X-ray (OPG): Rs 700.
3D scan (CBCT) for implants or aligners: Rs 3,000.'),((select id from d),'smile-point',3,'Cleaning','Scaling and polishing: Rs 1,500 per session. Takes about 45 minutes.
Deep cleaning (root planing), per quadrant: Rs 2,500.'),((select id from d),'smile-point',4,'Fillings','Tooth-coloured composite filling: Rs 1,200 per tooth.
Glass ionomer filling (temporary or kids): Rs 800.'),((select id from d),'smile-point',5,'Extractions','Simple tooth extraction: Rs 800.
Wisdom tooth extraction (erupted): Rs 2,500.
Wisdom tooth surgical removal (impacted): Rs 6,000 to Rs 12,000, depending on the X-ray.'),((select id from d),'smile-point',6,'Teeth Whitening','In-clinic laser whitening: Rs 12,000 for one session of 60 minutes.
Take-home whitening kit: Rs 6,500.'),((select id from d),'smile-point',7,'Root Canal','Root canal treatment (front tooth): Rs 5,500.
Root canal treatment (premolar): Rs 6,500.
Root canal treatment (molar): Rs 8,000. Crown is charged separately.
Re-root canal (redo of an old root canal): Rs 10,000.'),((select id from d),'smile-point',8,'Crowns and Bridges','Metal-ceramic crown: Rs 7,000. Zirconia crown: Rs 14,000.
Bridge: priced per unit at the crown rate (a 3-unit zirconia bridge is Rs 42,000).'),((select id from d),'smile-point',9,'Dental Implants','Single implant with crown (Korean system): Rs 30,000.
Single implant with crown (Swiss system, Straumann): Rs 55,000.
Implant price includes the surgery, abutment and crown. The CBCT scan is charged separately.'),((select id from d),'smile-point',10,'Dentures','Complete denture (one jaw): Rs 15,000. Both jaws: Rs 28,000.
Flexible partial denture: Rs 9,000.'),((select id from d),'smile-point',11,'Braces and Aligners','Metal braces: from Rs 35,000 for the full course.
Ceramic braces: from Rs 50,000 for the full course.
Clear aligners: from Rs 90,000. Final price after a 3D scan.'),((select id from d),'smile-point',12,'Kids','Child check-up (under 12): Rs 300. Fluoride application: Rs 800.
Pit and fissure sealant: Rs 700 per tooth.
Baby tooth root canal (pulpectomy): Rs 3,000.');
delete from documents where business_id='smile-point' and source_uri='smile-point/treatments.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('smile-point','smile-point/treatments.md','treatments','84dcfcd3caeedad9809c53fed65e68489c0c7e1fdef2f43aeea8724e2963e76f') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'smile-point',0,'How many visits does a root canal take','Most root canals are done in 1 or 2 visits of about 60 minutes each. A crown is fitted 1 to 2 weeks later.'),((select id from d),'smile-point',1,'Does a root canal hurt','The tooth is fully numbed with local anaesthesia, so most patients feel pressure, not pain. Mild soreness for 2 to 3 days afterwards is normal.'),((select id from d),'smile-point',2,'Implant timeline','The implant is placed in one visit. The crown is fitted after 3 to 4 months, once the implant has bonded with the bone.'),((select id from d),'smile-point',3,'Braces and aligner timeline','Braces and aligners usually take 12 to 24 months. Braces need a review visit every 4 to 6 weeks.'),((select id from d),'smile-point',4,'After a tooth extraction','Bite on the gauze for 30 minutes. Do not spit, rinse or use a straw for 24 hours. Eat soft, cold food on the first day. Call us if bleeding does not stop after a few hours.'),((select id from d),'smile-point',5,'Nervous patients','If you are anxious about dental treatment, tell us when you book. We give longer appointments, explain every step before we start, and you can raise your hand to pause at any time. We do not offer general anaesthesia or IV sedation.'),((select id from d),'smile-point',6,'Pregnancy','Check-ups and cleaning are safe during pregnancy, ideally in the second trimester. Tell us if you are pregnant; we avoid X-rays unless they are essential and we choose medicines that are safe in pregnancy.'),((select id from d),'smile-point',7,'Diabetes and heart conditions','Tell us about diabetes, blood pressure, heart conditions or blood thinners before treatment. Please take your usual medicines on the day. For extractions and implants we may ask for a recent blood sugar report.'),((select id from d),'smile-point',8,'Children''s first visit','We recommend a child''s first visit by their first birthday, or when the first tooth appears. Children''s appointments are kept short and friendly.'),((select id from d),'smile-point',9,'How often should I get a check-up','We recommend a check-up and cleaning every 6 months.'),((select id from d),'smile-point',10,'Bleeding gums','Bleeding gums are usually an early sign of gum disease. A scaling session and better brushing often fix it. Book a check-up if bleeding lasts more than a week.');
