insert into businesses (id,name,settings) values ('mclanefamilydental','McLane Family Dental','{"timezone": "America/Chicago", "country": "US", "demo_of": "https://mclanefamilydental.com/"}'::jsonb) on conflict (id) do update set name=excluded.name, settings=excluded.settings;
delete from documents where business_id='mclanefamilydental' and source_uri='mclanefamilydental/home.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('mclanefamilydental','mclanefamilydental/home.md','home','b42b37c36605203b10d2b4d82fb9351250f1817c803e5e1bbdc4503a1d6fd8cc') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'mclanefamilydental',0,'McLane Family Dental','Source: https://mclanefamilydental.com/ (scraped 2026-10-01, verbatim excerpts)'),((select id from d),'mclanefamilydental',1,'About','Compassionate, Comprehensive, Conservative Dental Care for Patients of All Ages.
Dr. James Mclane, Dr. Zachary Carlson, Dr. Deidra McLane.
At McLane Family Dental, every member of your family will receive compassionate, comprehensive, and conservative dental care in a comfortable environment. As your Austin family dentists we welcome patients of all ages. We take a personalized approach with each dental patient. We will take time to understand your needs, so we can provide an individualized plan for attaining and maintaining optimal oral health.'),((select id from d),'mclanefamilydental',2,'Featured Services','General Dentistry. Cosmetic Dentistry. Restorative Dentistry. Sedation Dentistry.'),((select id from d),'mclanefamilydental',3,'New Patients','We Are accepting new patients. Make appointment: https://mclanefamilydental.com/contact-us/'),((select id from d),'mclanefamilydental',4,'Meet the Doctors','Dr. Deidra was born and raised in Lubbock, Texas. She graduated from the top ranked UT Health Science Center at San Antonio Dental School in 2007.
Dr. James graduated Summa Cum Laude from Texas A&M University before attending the UT Health Science Center at San Antonio Dental School, graduating in 2007.
Dr. Zachary Carlson attended Texas A&M Health Science Center Baylor College of Dentistry in Dallas. He has been providing patient-tailored dental care in south Austin since 2018. His favorite aspects of dentistry are forming authentic lasting connections with patients and helping alleviate the concerns of the dentally anxious.'),((select id from d),'mclanefamilydental',5,'Office Schedule','Mon. 8am – 5pm. Tue. 8am – 5pm. Wed. 8am – 5pm. Thu. 8am – 5pm. Fri. Closed. Sat. Closed. Sun. Closed.'),((select id from d),'mclanefamilydental',6,'Contact','Phone: 512.292.8002
Address: 5000 W. Slaughter Lane, Suite 200, Austin, TX 78749');
insert into businesses (id,name,settings) values ('hillcountryfamilydental','Hill Country Family Dental','{"timezone": "America/Chicago", "country": "US", "demo_of": "https://hillcountryfamilydental.com/"}'::jsonb) on conflict (id) do update set name=excluded.name, settings=excluded.settings;
delete from documents where business_id='hillcountryfamilydental' and source_uri='hillcountryfamilydental/faq.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('hillcountryfamilydental','hillcountryfamilydental/faq.md','faq','15b45a2e3ebe78c9bd8a418fe40f470d1de1eb21587d8c9e3a8f4c5426272420') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'hillcountryfamilydental',0,'Hill Country Family Dental — Frequently Asked Questions','Source: https://hillcountryfamilydental.com/faq.html and homepage (scraped 2026-10-01, verbatim excerpts)'),((select id from d),'hillcountryfamilydental',1,'Contact and hours','12129 North FM 620, Suite 300, Austin, TX 78750. Phone (512) 249-9147. Dr. Eric Vetter.
Monday: 8am - 5pm. Tuesday: 8am - 5pm. Wednesday: 8am - 5pm. Thursday: 8am - 5pm. Fri - Sun: Closed.
Payment: Cash, Check, MasterCard, Visa, American Express, Discover, Most Dental Insurance Plans, CareCredit.
Appointments are requested at https://hillcountryfamilydental.com/request-appt-wizard.html'),((select id from d),'hillcountryfamilydental',2,'New patient specials','$49 Emergency Exam & X-ray. Free Exam & X-ray With Purchase of Cleaning. New patients only. Not valid with any insurance. In absence of periodontal or gum disease.'),((select id from d),'hillcountryfamilydental',3,'Do root canals hurt?','Today, with modern technology and better anesthetics, most patients report a pain-free experience and can expect very little discomfort. Your doctor explains all procedures to our patients, which helps ease a lot of anxiety.'),((select id from d),'hillcountryfamilydental',4,'Do root canals require many visits to the dentist?','With today''s cutting edge technology, most root canal procedures can be performed in one or two office visits. Please remember the length of the procedure and the number of appointments depends on many patient specific factors.'),((select id from d),'hillcountryfamilydental',5,'Can antibiotics cure a root canal?','The only way to cure a root canal infection is to manually remove the infection from the canal of the tooth. Antibiotics can be useful to suppress symptoms such as biting pain before the root canal and may even help prevent post treatment pain. However, antibiotics cannot cure a root canal infection.'),((select id from d),'hillcountryfamilydental',6,'Do you accept my insurance?','In many cases insurance will pay for all or most of your treatment. When you call to make your appointment, have all of your information ready and we will be able to provide you with more information.'),((select id from d),'hillcountryfamilydental',7,'How much does it cost?','The cost associated with endodontic therapy depends on a variety of factors including the severity of the damage to the tooth. In general, it is much more cost effective to save an infected tooth as opposed to letting the infection spread or remove it and replace it with an artificial tooth.'),((select id from d),'hillcountryfamilydental',8,'Can I drive myself home after the procedure?','Most treatments are performed using local anesthetic and its effects do not impair driving. Patients utilizing oral sedation will need a driver to bring them to and from their appointment on the day of their procedure.'),((select id from d),'hillcountryfamilydental',9,'Should I be worried about radiation exposure from the x-rays?','We only take x-rays when necessary to provide the best treatment possible. Our advanced x-ray system is digital and produces radiation levels up to 90 percent lower than the already low dose traditional dental x-rays.'),((select id from d),'hillcountryfamilydental',10,'Do I have to see my dentist after my root canal?','After the root canal is complete and the pulp is removed, your tooth is at risk for fracturing. A permanent restoration will protect your tooth from fracturing and becoming contaminated. This is why your doctor advises you to return to your doctor within 3 weeks after your root canal.');
insert into businesses (id,name,settings) values ('austinsimplyfit','Austin Simply Fit','{"timezone": "America/Chicago", "country": "US", "demo_of": "https://www.austinsimplyfit.com/"}'::jsonb) on conflict (id) do update set name=excluded.name, settings=excluded.settings;
delete from documents where business_id='austinsimplyfit' and source_uri='austinsimplyfit/get-started.md';
with d as (insert into documents (business_id,source_uri,title,content_hash) values ('austinsimplyfit','austinsimplyfit/get-started.md','get-started','47b82293e0d306743dca82f34aa47050179cb8ec70875dad4edf1ae9179e4e70') returning id) insert into chunks (document_id,business_id,ord,heading,body) values ((select id from d),'austinsimplyfit',0,'Austin Simply Fit — Get Started and Programs','Source: https://www.austinsimplyfit.com/get-started/ and /personal-training-programs/ (scraped 2026-10-01, verbatim excerpts)'),((select id from d),'austinsimplyfit',1,'Get Started','A member of our team will reach out to help you set up your FREE consultation and assessment. Complete the form below to schedule a session with a personal trainer.'),((select id from d),'austinsimplyfit',2,'How do I get started with personal training at Austin Simply Fit?','Fill out the contact form on the Get Started page with your name, email, and phone number. A member of the ASF team will reach out within 24 hours (one business day) to schedule your free one-hour consultation and structural balance assessment. There''s no commitment required — the consultation is completely complimentary.'),((select id from d),'austinsimplyfit',3,'What is included in the free consultation at Austin Simply Fit?','Your free consultation is a full hour and has two parts. The first part is a conversation with your personal trainer covering your health and fitness goals, medical history, and training background, plus a walkthrough of ASF''s training programs, packages, and studio policies. The second part is a hands-on structural balance assessment where your trainer evaluates your movement quality and fitness level. You also receive a free body composition analysis using ASF''s InBody machine.'),((select id from d),'austinsimplyfit',4,'How long does it take to hear back after submitting the Get Started form?','ASF aims to respond within 24 hours (one business day) of receiving your form submission. You can also call or email either studio location, ASF Central on Burnet Rd or ASF South on South Lamar.'),((select id from d),'austinsimplyfit',5,'What should I bring or do to prepare for my first visit?','After your consultation is scheduled, you will receive an intake form to complete before meeting with your trainer. For your consultation, wear comfortable workout clothes and athletic shoes. After your consultation, you''ll also receive ASF''s Wellness Packet with lifestyle and recovery recommendations.'),((select id from d),'austinsimplyfit',6,'What happens after the free consultation? Am I locked into anything?','No. If you decide to move forward, you and your trainer will find a mutually convenient schedule and book your ongoing training sessions. There are no memberships or long-term contracts. Sessions are purchased in packages of 5, 10, or 20.'),((select id from d),'austinsimplyfit',7,'Can I request a specific trainer at Austin Simply Fit?','You can share preferences, and ASF will do their best to accommodate. Trainer matching is primarily based on schedule availability and fit for your specific goals. Some trainers specialize in athletic development, injury rehabilitation, or pre- and postnatal exercise, but all ASF trainers complete the same rigorous 13-week onboarding program.'),((select id from d),'austinsimplyfit',8,'How is Austin Simply Fit different from signing up at a commercial gym?','Every session is by appointment with a dedicated certified trainer who has designed a program specifically for you. There are no crowds, no waiting for equipment, and no generic workouts. ASF operates as a private personal training studio, built around focused 30-minute sessions.'),((select id from d),'austinsimplyfit',9,'Personal Training Programs','One-on-One Personal Training: private, one-on-one 30-minute training sessions with a Certified Personal Trainer.
Multi-Client Personal Training: semi-private, two or three clients train together in 30-minute sessions with a Certified Personal Trainer.
We also offer virtual training to keep you consistent at home or while traveling. Nutrition and health coaching through THRIVE with Keyspan at Austin Simply Fit.'),((select id from d),'austinsimplyfit',10,'Locations','Central Austin Simply Fit: 4912 Burnet Rd., Austin, Texas 78756. (512) 502-5032. info@austinsimplyfit.com
South Austin Simply Fit: 1621 S Lamar Blvd., Austin, Texas 78704. (512) 502-5032. info@austinsimplyfit.com');
